function estimate(a){if(a.shootType==='Business / branding'){if(!text(a.businessName,120))bad('Enter your business name');if(!text(a.businessUse,300))bad('Tell us where the photographs will be used');return {version:'2026-10-12',package:'business',label:'Business / branding',minutes:null,images:null,travelZone:a.travelZone||'custom',total:null,currency:'USD',customQuote:true,travelVerified:false};}const pkg=PACKAGES[a.sessionPackage];if(!pkg)bad('Choose a session option');const people=Number(a.people);if(!Number.isInteger(people)||people<1||people>1000)bad('Enter number of people');const travel={local:0,near:20,far:35,custom:null}[a.travelZone];if(travel===undefined)bad('Choose a location distance');const custom=a.shootType==='Wedding'||a.shootType==='Other — describe below'||travel===null||(a.sessionPackage==='mini'&&people!==1)||(a.sessionPackage==='friends'&&(people!==2||a.shootType!=='Graduation / portraits'))||(a.sessionPackage==='full'&&people>2);return {version:'2026-10-08',package:a.sessionPackage,label:pkg.label,minutes:pkg.minutes,images:pkg.images,travelZone:a.travelZone,total:custom?null:pkg.price+travel,currency:'USD',customQuote:custom,travelVerified:false};}
const TASKS = ['RAW files imported','RAW files backed up','Photos culled','Selects finalized','Lightroom edits completed','Photoshop work completed if necessary','Final images exported','Final images reviewed','Gallery uploaded','Gallery delivery email prepared','Gallery delivered','Client follow-up scheduled','Review/referral request scheduled when appropriate','Files archived'];
