const json = (v,status=200) => new Response(JSON.stringify(v),{status,headers:{...security,'Content-Type':'application/json'}});
const html = v => {const nonce=crypto.randomUUID();return new Response(v.replaceAll('nonce="__SCRIPT_NONCE__"','nonce="'+nonce+'"'),{headers:{...security,'Content-Security-Policy':security['Content-Security-Policy'].replace("script-src 'self' 'unsafe-inline'","script-src 'self' 'nonce-"+nonce+"'"),'Content-Type':'text/html; charset=utf-8'}});};
const isPending = r => r.kind!=='print' && !['BOOKED','COMPLETED','REJECTED','CANCELLED'].includes(r.status);
function widgetSnapshot(records, now = new Date()) {
 const timeZone = 'America/New_York';
 const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {timeZone, year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value]));
 const today = parts.year+'-'+parts.month+'-'+parts.day, clock = parts.hour+':'+parts.minute;
 const booked = records.filter(r=>r.status==='BOOKED').sort((a,b)=>((a.date||'9999')+'T'+(a.time||'99')).localeCompare((b.date||'9999')+'T'+(b.time||'99'))||a.id.localeCompare(b.id));
 const shoot = r => ({id:r.id,client:r.client||'Client',shootType:r.shootType||'',date:r.date||null,time:r.time||null,url:'/widget?record='+encodeURIComponent(r.id)});
 const scheduled = booked.filter(r=>/^\d{4}-\d{2}-\d{2}$/.test(r.date||'')&&/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time||''));
 const next = scheduled.find(r=>r.date>today||r.date===today&&r.time>=clock);
 return {schemaVersion:1,timeZone,generatedAt:now.toISOString(),refreshAfterSeconds:900,toBook:records.filter(r=>r.kind!=='print'&&!['BOOKED','COMPLETED','REJECTED','CANCELLED'].includes(r.status)).length,pendingUrl:'/widget?view=inbox',dashboardUrl:'/widget',today:booked.filter(r=>r.date===today).map(shoot),nextShoot:next?shoot(next):null,unscheduledBooked:booked.length-scheduled.length};
}
const owner = r => !!r.headers.get('oai-authenticated-user-id') && r.headers.get('oai-authenticated-user-email')?.toLowerCase() === OWNER;
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => {const n=Number(v); if(v===''||v==null)return null;if(!Number.isFinite(n)||n<0||n>1000000)throw new Error('Invalid amount');return Math.round(n*100)/100};
const validDate = v => !v || /^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
const agentView = value => Array.isArray(value)?value.map(agentView):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).filter(([k])=>!['finances','payment','agreedPrice','priceEvidence','payments','paymentsReceived','balance','printLabCost','labShipping','clientShipping','packagingCost','paymentFees','otherPrintCosts'].includes(k)).map(([k,v])=>[k,agentView(v)])):value;
const bad = message => {throw new Error(message)};
const text = (v,max=2000) => typeof v === 'string' && v.length <= max ? v.trim() : v == null ? '' : bad('Invalid text');
const validId = v => typeof v==='string' && /^[a-zA-Z0-9_-]{1,100}$/.test(v) ? v : bad('Invalid record ID');
function calendarNote(date,time,duration=null) {
 if(!date)return 'Date needed. Calendar, travel and preparation need review.';
 if(date>'2026-12-15')return 'Tentative: future class schedule unknown; confirmation required.';
 const day=new Date(date+'T12:00:00Z').getUTCDay();
 const blocks=day===1||day===3?[[480,530],[540,590],[930,1005]]:day===2?[[570,645],[930,1005],[1095,1245]]:day===4?[[570,645],[930,1005]]:day===5?[[480,530],[540,590]]:[];
 if(!time)return 'Time needed. Review the detailed class schedule and calendar.';
 const [h,m]=time.split(':').map(Number),start=h*60+m,end=start+(duration||1);
 if(blocks.some(([a,b])=>start<b&&end>a))return 'CONFLICT with known class time (Eastern). Choose another time.';
 return (duration?'No known class overlap. ':'Duration unknown; overlap cannot be ruled out. ')+'Google Calendar, private Outlook, travel and preparation still need review.';
}
const PRINT_STAGES=['INQUIRY','QUOTED','READY TO ORDER','ORDERED FROM LAB','RECEIVED / INSPECT','SIGNED','SHIPPED TO CLIENT','DELIVERED'];
const STAGES=['NOT STARTED','NEEDS IMPORT','CULLING','EDITING','READY TO DELIVER','DELIVERED'];
const RESPONSES=['NONE','NEEDS MY REPLY','WAITING ON CLIENT'];
function operationsFields(a){
 const next={};
 for(const k of ['printLabCost','labShipping','clientShipping','packagingCost','paymentFees','otherPrintCosts'])if(k in a)next[k]=money(a[k]);
 if('printStage' in a){if(!PRINT_STAGES.includes(a.printStage))bad('Invalid print stage');next.printStage=a.printStage;}
 for(const k of ['labOrderReference','printTracking','signatureNotes'])if(k in a)next[k]=text(a[k],1000);
 for(const k of ['editingStage','responseState','dueDate','followUpDate','lastContactDate','folderLink','galleryLink','lightroomLink','marketingSource','imageCount','editingScope','turnaround','prepNotes','backupNotes','nextAction','draft','calendarEventLink'])if(k in a)next[k]=text(a[k],k==='draft'?6000:2000);
 if(next.editingStage&&!STAGES.includes(next.editingStage))bad('Invalid editing stage');
 if(next.responseState&&!RESPONSES.includes(next.responseState))bad('Invalid response state');
 for(const k of ['dueDate','followUpDate','lastContactDate'])if(k in next&&!validDate(next[k]))bad('Invalid date');
 for(const k of ['folderLink','galleryLink','lightroomLink','calendarEventLink'])if(next[k]&&!/^https:\/\//.test(next[k]))bad('Links must use HTTPS');
 if(next.imageCount&&!/^\d{1,5}$/.test(next.imageCount))bad('Image count must be a whole number');
 return next;
}
async function body(r) {
 if(Number(r.headers.get('content-length')||0)>24000) bad('Request too large');
 const raw=await r.text(); if(raw.length>24000) bad('Request too large'); return JSON.parse(raw);
}
async function load(env,id) {const o=await env.BUCKET.get('records/'+validId(id)+'.json');return o?{data:await o.json(),etag:o.etag}:null;}
async function list(env,cursor) {
 const r=await env.BUCKET.list({prefix:'records/',limit:200,cursor:cursor||undefined});
 const records=await Promise.all(r.objects.map(async o=>{const x=await env.BUCKET.get(o.key);return x?await x.json():null}));
 return {records:records.filter(Boolean).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)),cursor:r.truncated?r.cursor:null};
}
async function put(env,id,data,etag) {
 const result=await env.BUCKET.put('records/'+validId(id)+'.json',JSON.stringify(data),{httpMetadata:{contentType:'application/json'},onlyIf:etag?{etagMatches:etag}:{etagDoesNotMatch:'*'}});
 if(!result) bad('Record changed. Refresh before retrying.'); return data;
}
async function upsert(env,a) {
 if(['agreedPrice','priceEvidence','finances','payment','payments','balance'].some(k=>k in a))bad('Payment records are owner-only and unavailable to automation');
 const id=validId(a.id), existing=await load(env,id), previous=existing?.data||{};
 if(a.expectedUpdatedAt && a.expectedUpdatedAt!==previous.updatedAt) bad('Record changed. Refresh before retrying.');
 if(a.status&&!STATUSES.includes(a.status)) bad('Invalid status');
 if(['REJECTED','CANCELLED'].includes(a.status)&&a.status!==previous.status)bad('Use owner dashboard to reject or cancel');
 if(a.status==='BOOKED'&&previous.status!=='BOOKED'&&!a.bookingApprovalEvidence) bad('Explicit booking approval evidence required');
 const next={...previous,...operationsFields(a),id,kind:a.kind||previous.kind||'inquiry',createdAt:previous.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
 if(!['inquiry','shoot','print'].includes(next.kind)) bad('Invalid record kind');
 for(const k of ['client','email','phone','shootType','date','time','location','people','requests','asked','missing','availability','nextAction','draft','source','sourceUrl','dueDate','contract','bookingApprovalEvidence','description','duration','travel','specialNotes']) if(k in a) next[k]=text(a[k],k==='draft'?6000:2000);
 if(next.sourceUrl && !/^https:\/\//.test(next.sourceUrl)) bad('Source URL must use HTTPS');
 next.status=a.status||previous.status||'NEW';
 if(a.tasks){if(!Array.isArray(a.tasks)||a.tasks.length>50)bad('Invalid tasks');next.tasks=a.tasks.map(t=>({id:validId(t.id),label:text(t.label,200),state:['pending','complete','not-needed'].includes(t.state)?t.state:'pending',evidence:text(t.evidence,1000),dueDate:text(t.dueDate,30)})); if(next.tasks.some(t=>t.state!=='pending'&&!t.evidence))bad('Completed and not-needed tasks require evidence');}
 return put(env,id,next,existing?.etag);
}
