 const quote=(a.sessionPackage||shootType==='Business / branding')?estimate(a):null;const hours=quote?(quote.minutes==null?null:quote.minutes/60):a.hours==null||a.hours===''?null:Number(a.hours);if(hours!==null&&(!Number.isFinite(hours)||hours<0.25||hours>24))bad('Invalid shoot length');const location=text(a.location,500),people=text(a.people,10);if(people&&(!/^\d+$/.test(people)||Number(people)<1||Number(people)>1000))bad('Invalid number of people');
 const now=new Date().toISOString();await put(env,id,{id,kind:'inquiry',estimate:quote,sessionPackage:a.sessionPackage||'',imageCount:quote?.images!=null?String(quote.images):'',turnaround:quote&&!quote.customQuote?'14 calendar days':'',smsConsent:a.smsConsent===true,smsConsentAt:a.smsConsent===true?new Date().toISOString():null,client,email,phone:text(a.phone,40),shootType,date,time,location,people,requests,duration:hours?hours+' hours':'',asked:a.pricing?'Asked for pricing':'See client request',status:'NEW',source:'Website request',marketingSource:text(a.marketingSource,120),responseState:'NEEDS MY REPLY',availability:calendarNote(date,time,hours?hours*60:null),missing:[!date?'date':'',!time?'time':'',!location?'location':'',!hours?'duration':'','travel/preparation','Google Calendar review','final approval'].filter(Boolean).join(', '),nextAction:'Review inquiry and prior Gmail communication; prepare a response for approval.',createdAt:now,updatedAt:now});return json({id},201);
