async function publicInquiry(r,env,path) {
 const origin=r.headers.get('Origin');
 const allowed=origin===new URL(r.url).origin||['https://madmanphoto.com','https://www.madmanphoto.com'].includes(origin);
 if(!allowed)return json({error:'Request origin not allowed'},403);
 const cors={'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Methods':'POST, OPTIONS','Access-Control-Allow-Headers':'Content-Type','Vary':'Origin'};
 if(r.method==='OPTIONS')return new Response(null,{status:204,headers:cors});
 let response;
 try {
  if(r.method!=='POST')response=json({error:'Method not allowed'},405);
  else response=path==='/api/estimate'?json(estimate(await body(r))):await intake(r,env);
 }catch(e){response=json({error:e instanceof SyntaxError?'Invalid JSON':e.message},400);}
 const headers=new Headers(response.headers);for(const [key,value] of Object.entries(cors))headers.set(key,value);
 return new Response(response.body,{status:response.status,headers});
}
